import type {WsAuthenticator, HttpAuthMiddleware} from './types/auth.js';
import type {SessionStore} from './types/sessionStore.js';
import type {PromptBuilderConfig} from './infrastructure/builders/promptBuilder.js';
import type {ContextConfig} from './orchestration/conversationContext.js';
import type {ProviderConfig} from './providers/providerFactory.js';
import {withRetry} from './providers/withRetry.js';
import type {RetryPolicy} from './providers/withRetry.js';
import type {Logger} from './shared/logger.js';
import {setLogger} from './shared/logger.js';
import type {ChatSession} from './types/session.js';
import type {HalServer} from './transport/createServer.js';
import type {ConnectInfo} from './transport/ws/sessionResume.js';
import {PromptBuilder} from './infrastructure/builders/promptBuilder.js';
import {createChatOrchestrator} from './orchestration/chatOrchestrator.js';
import type {OrchestratorHooks} from './orchestration/chatOrchestrator.js';
import {createProvider} from './providers/providerFactory.js';
import {ToolRegistry} from './orchestration/tools/registry.js';
import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
import {createApp} from './transport/createApp.js';
import type {HalAppOptions} from './transport/createApp.js';
import {createServer} from './transport/createServer.js';
import type {SessionResumeOptions} from './transport/ws/sessionResume.js';

export interface HalEngineConfig {
  provider: ProviderConfig;
  resilience?: RetryPolicy;
  prompt: PromptBuilderConfig;
  tools?: ToolRegistry;
  session?: SessionStore;
  transport?: {
    port?: number;
    corsOrigin?: string | string[];
    basePath?: string;
    heartbeatIntervalMs?: number;
    additionalRoutes?: HalAppOptions['additionalRoutes'];
    rootRoutes?: HalAppOptions['rootRoutes'];
    errorHandler?: HalAppOptions['errorHandler'];
    resume?: SessionResumeOptions;
  };
  auth: {
    ws: WsAuthenticator;
    http?: HttpAuthMiddleware;
  };
  orchestrator?: {
    maxToolRounds?: number;
    /** How long one tool call may take before it is abandoned and answered with a timeout result; default 30000, and 0 waits forever. */
    toolTimeoutMs?: number;
    contextConfig?: Partial<ContextConfig>;
    /** Lifecycle hooks: called before and after each phase of processing a user message. */
    hooks?: OrchestratorHooks;
  };
  // Replaces the package's logger process-wide, not per engine: there is one `log` per process.
  logger?: Logger;
  onConnect?: (session: ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
}

export interface HalEngine extends HalServer {
  app: ReturnType<typeof createApp>;
  orchestrator: ReturnType<typeof createChatOrchestrator>;
  toolRegistry: ToolRegistry;
}

export function createHalEngine(config: HalEngineConfig): HalEngine {
  // Before anything else builds, so a supplied logger receives this engine's first line.
  if (config.logger) setLogger(config.logger);

  const toolRegistry = config.tools ?? new ToolRegistry();
  const sessionStore = config.session ?? new InMemorySessionStore();
  const basePath = config.transport?.basePath ?? '/hal';

  const baseProvider = createProvider(config.provider);
  const provider = config.resilience ? withRetry(baseProvider, config.resilience) : baseProvider;
  const promptBuilder = new PromptBuilder(config.prompt);
  const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
    maxToolRounds: config.orchestrator?.maxToolRounds,
    toolTimeoutMs: config.orchestrator?.toolTimeoutMs,
    contextConfig: config.orchestrator?.contextConfig,
    hooks: config.orchestrator?.hooks,
    sessionStore,
  });

  const app = createApp({
    corsOrigin: config.transport?.corsOrigin,
    basePath,
    authMiddleware: config.auth.http,
    orchestrator,
    sessionStore,
    additionalRoutes: config.transport?.additionalRoutes,
    rootRoutes: config.transport?.rootRoutes,
    errorHandler: config.transport?.errorHandler,
  });

  const halServer = createServer({
    app,
    wsAuth: config.auth.ws,
    sessionStore,
    orchestrator,
    toolRegistry,
    basePath,
    port: config.transport?.port,
    heartbeatIntervalMs: config.transport?.heartbeatIntervalMs,
    onConnect: config.onConnect,
    onDisconnect: config.onDisconnect,
    resume: config.transport?.resume,
  });

  return {
    ...halServer,
    app,
    orchestrator,
    toolRegistry,
  };
}

import http from 'http';
import {WebSocketServer} from 'ws';
import type {Express} from 'express';
import type {WsAuthenticator} from '../types/auth.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {ToolRegistry} from '../orchestration/tools/registry.js';
import {createUpgradeHandler, createConnectionHandler, ExtWebSocket} from './ws/connectionHandler.js';
import {createMessageHandler} from './ws/messageHandler.js';
import {selectSubprotocol} from './ws/subprotocol.js';
import type {ConnectInfo, SessionResumeOptions} from './ws/sessionResume.js';
import {log} from '../shared/logger.js';

export interface HalServerOptions {
  app: Express;
  wsAuth: WsAuthenticator;
  sessionStore: SessionStore;
  orchestrator: ChatOrchestrator;
  toolRegistry?: ToolRegistry;
  basePath?: string;
  port?: number;
  heartbeatIntervalMs?: number;
  onConnect?: (session: import('../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
  resume?: SessionResumeOptions;
}

export interface HalServer {
  server: http.Server;
  wss: WebSocketServer;
  start: (port?: number) => Promise<void>;
  stop: () => Promise<void>;
}

export function createServer(options: HalServerOptions): HalServer {
  const basePath = options.basePath ?? '/hal';

  const wss = new WebSocketServer({
    noServer: true,
    handleProtocols: selectSubprotocol,
  });

  const handleMessage = createMessageHandler(options.orchestrator);
  const examplePrompts = options.toolRegistry?.getExamplePrompts() ?? [];

  const deps = {
    wsAuth: options.wsAuth,
    sessionStore: options.sessionStore,
    handleMessage,
    basePath,
    onConnect: options.onConnect,
    onDisconnect: options.onDisconnect,
    resume: options.resume,
  };

  const handleUpgrade = createUpgradeHandler(wss, deps);
  const handleConnection = createConnectionHandler(deps, examplePrompts);

  const server = http.createServer(options.app);

  server.on('upgrade', (request, socket, head) => {
    handleUpgrade(request, socket, head);
  });

  wss.on('connection', ws => {
    handleConnection(ws as ExtWebSocket);
  });

  const heartbeatMs = options.heartbeatIntervalMs ?? 30_000;

  const heartbeatInterval = setInterval(() => {
    wss.clients.forEach(ws => {
      const extWs = ws as ExtWebSocket;
      if (!extWs.isAlive) {
        extWs.terminate();
        return;
      }
      extWs.isAlive = false;
      extWs.ping();
    });
  }, heartbeatMs);

  // The listening socket should hold the process open, not the heartbeat: an engine never started must not.
  heartbeatInterval.unref();

  wss.on('close', () => clearInterval(heartbeatInterval));

  return {
    server,
    wss,
    start: (port?: number) =>
      new Promise<void>((resolve, reject) => {
        // Refused before the handlers are touched: `listen` throws on a running server, and the swap below stripped its handler.
        if (server.listening) {
          reject(new Error('HAL Engine is already started'));
          return;
        }

        // ?? not ||, so a configured port 0 means "let the OS choose" rather than 8086.
        const p = port ?? options.port ?? (Number(process.env.PORT) || 8086);

        // Without this an EADDRINUSE settles nothing and takes the process down as an unhandled event.
        const onError = (error: Error) => reject(error);
        server.once('error', onError);

        // A listener left from a previous start would report this bind failure as a running server breaking.
        server.removeListener('error', logLateError);

        server.listen(p, () => {
          server.removeListener('error', onError);

          // Past the listen window nothing is listening, and an 'error' with no handler ends the process.
          server.on('error', logLateError);

          // The bound port, not the requested one: a configured 0 means the OS chose it.
          log.info('server', 'HAL Engine started', {port: boundPort(server, p)});
          resolve();
        });
      }),
    stop: () =>
      new Promise<void>((resolve, reject) => {
        wss.clients.forEach(ws => ws.close(1001, 'Server shutting down'));
        wss.close();
        clearInterval(heartbeatInterval);

        // Nothing to close after a refused start or a second stop: `close` would reject for a server that never ran.
        if (!server.listening) {
          resolve();
          return;
        }
        server.close(err => (err ? reject(err) : resolve()));
      }),
  };
}

// A running server's error is a condition to report, not a reason to exit; the consumer decides what to do.
function logLateError(error: Error): void {
  log.error('server', 'server error after start', {error: error.message});
}

function boundPort(server: http.Server, requested: number): number {
  const address = server.address();
  return typeof address === 'object' && address !== null ? address.port : requested;
}

import {WebSocket, WebSocketServer} from 'ws';
import {IncomingMessage} from 'http';
import {Duplex} from 'stream';
import {v4 as uuidv4} from 'uuid';
import type {WsAuthenticator} from '../../types/auth.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {ConnectedMessage} from '../../types/messages.js';
import type {AuthenticatedUser, ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/session.js';
import {sendError} from './sender.js';
import {isValidWsPath, rejectSocket, parseWsData, sessionIdFromUpgrade, newSessionRequested} from './helpers.js';
import {credentialFromSubprotocol} from './subprotocol.js';
import {replayEntries, resumableSession, resumeFields} from './sessionResume.js';
import type {ConnectInfo, SessionResumeOptions} from './sessionResume.js';
import {log} from '../../shared/logger.js';

export interface ExtWebSocket extends WebSocket {
  isAlive: boolean;
  userId: string | number;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
  requestedSessionId?: string;
  startNewSession?: boolean;
}

export interface ConnectionHandlerDeps {
  wsAuth: WsAuthenticator;
  sessionStore: SessionStore;
  /** `signal` is the connection's own, aborted when its socket closes (specs/hal-engine-abandon-on-close/spec.md). */
  handleMessage: (
    ws: WebSocket,
    session: import('../../types/session.js').ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ) => Promise<void>;
  basePath: string;
  onConnect?: (session: import('../../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
  resume?: SessionResumeOptions;
}
export function createUpgradeHandler(wss: WebSocketServer, deps: ConnectionHandlerDeps) {
  return function handleUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer): void {
    // Nothing may throw out of this listener: the `upgrade` event has no catch above it, so a throw ends the process.
    if (!request.headers.host || !isValidWsPath(request.url || '', deps.basePath)) {
      rejectSocket(socket, '400 Bad Request');
      return;
    }

    authenticate(deps.wsAuth, request)
      .then(user => {
        if (!user) {
          rejectSocket(socket, '401 Unauthorized');
          return;
        }

        wss.handleUpgrade(request, socket, head, ws => {
          const extWs = ws as ExtWebSocket;
          extWs.userId = user.id;
          extWs.workspaceId = user['workspaceId'] as string | number | undefined;
          extWs.authHeaders = {
            cookie: request.headers.cookie,
            authorization: request.headers.authorization || bearerFromWebSocketProtocol(request),
            host: (request.headers['x-forwarded-host'] as string | undefined) ?? request.headers.host,
          };
          extWs.isAlive = true;
          if (deps.resume?.enabled) {
            extWs.requestedSessionId = sessionIdFromUpgrade(request.url || '', deps.basePath);
            extWs.startNewSession = newSessionRequested(request.url || '', deps.basePath);
          }
          wss.emit('connection', extWs, request);
        });
      })
      .catch((error: unknown) => {
        // The type alone: an authenticator's message can carry the credential it was checking.
        log.error('ws', 'authenticator failed', {errorType: error instanceof Error ? error.name : typeof error});
        rejectSocket(socket, '500 Internal Server Error');
      });
  };
}

// Async, so a synchronous throw becomes a rejection (answered 500) and a user returned without a promise still resolves.
async function authenticate(wsAuth: WsAuthenticator, request: IncomingMessage): Promise<AuthenticatedUser | null> {
  return wsAuth(request);
}

function bearerFromWebSocketProtocol(req: IncomingMessage): string | undefined {
  const token = credentialFromSubprotocol(req.headers['sec-websocket-protocol']);
  return token ? `Bearer ${token}` : undefined;
}

export function createConnectionHandler(deps: ConnectionHandlerDeps, examplePrompts: string[]) {
  return function handleConnection(ws: ExtWebSocket): void {
    // The listener stays synchronous: an async one rejects into the emitter, and node ends the process on that.
    openSession(deps, examplePrompts, ws).catch((error: unknown) => {
      log.error('ws', 'connection setup failed', {error: messageOf(error)});
      // Resumed before closing: a paused socket never reads the close frame it would be waiting for.
      ws.resume();
      ws.close(1011, 'Connection setup failed');
    });
  };
}

// The sockets open on each session, oldest first: a resumed session can be open on more than one at once.
const openSockets = new WeakMap<ChatSession, ExtWebSocket[]>();

async function openSession(deps: ConnectionHandlerDeps, examplePrompts: string[], ws: ExtWebSocket): Promise<void> {
  // A requested id is never adopted for a new session: that would be session fixation.
  let sessionId = uuidv4();
  const state = {closed: false, settled: false, notified: false, delivered: false};
  const held: {session?: ChatSession; socket: ExtWebSocket} = {socket: ws};
  // One per connection, not per message or session: a close abandons the turn in flight and every message queued behind it.
  const connection = new AbortController();

  ws.on('error', (error: Error) => {
    log.error('ws', 'connection error', {sessionId, error: error.message});
  });

  ws.on('pong', () => {
    ws.isAlive = true;
  });

  ws.on('close', () => {
    // First, so the turn stops before the session is torn down and before onDisconnect.
    connection.abort();
    state.closed = true;
    log.info('ws', 'disconnected', {sessionId});
    if (state.settled) endSession(deps, sessionId, state, held);
  });

  // Paused across the await so a frame arriving before the message listener exists is buffered, not dropped.
  ws.pause();

  const outcome = await resumableSession(deps.sessionStore, ws, deps.resume);
  const resumed = outcome.session;
  if (resumed) sessionId = resumed.sessionId;
  const session = resumed ?? (await createSession(deps, sessionId, ws));
  state.settled = true;

  if (session === undefined) {
    // Resumed before closing: ws.close() on a paused socket waits for a close frame it can never read.
    ws.resume();
    ws.close(1011, 'Session store unavailable');
    return;
  }

  // A new session is this socket's from the start; a resumed one only once this socket is known to be open.
  if (!resumed) join(session, ws);

  if (state.closed) {
    // Held first: a store that implements no evict still holds this session, and it carries the caller's credentials.
    held.session = session;
    await evictUnlessResumed(deps, sessionId, resumed);
    endSession(deps, sessionId, state, held);
    ws.resume();
    return;
  }

  if (resumed) join(resumed, ws);
  held.session = session;

  log.info('ws', 'connected', {sessionId, userId: ws.userId});

  const connected: ConnectedMessage = {
    type: 'connected',
    sessionId,
    message: 'Connected to HAL Engine',
    examplePrompts,
    ...resumeFields(deps.resume, outcome),
  };
  // A socket that died between the check above and this frame must not leave the session it was created for behind.
  try {
    ws.send(JSON.stringify(connected));
    if (resumed) replayEntries(ws, resumed);
  } catch (error) {
    log.error('ws', 'connected frame failed', {sessionId, error: messageOf(error)});
    await evictUnlessResumed(deps, sessionId, resumed);
    endSession(deps, sessionId, state, held);
    ws.resume();
    ws.close(1011, 'Connection setup failed');
    return;
  }

  state.delivered = true;

  // Deferred, not inline: a synchronous throw in the `connection` listener corrupts an already-upgraded socket.

  // A microtask, not setImmediate: it drains before the loop delivers any inbound frame on this socket.
  queueMicrotask(() =>
    runHook('onConnect', sessionId, () => deps.onConnect?.(session, {resumed: resumed !== undefined}))
  );

  ws.on('message', (frame: Buffer | string) => {
    const parsed = parseWsData(frame);
    if (parsed === null) {
      sendError(ws, ErrorCodes.INVALID_FORMAT, 'Invalid JSON');
      return;
    }
    log.info('ws', 'message received', {sessionId, type: (parsed as Record<string, unknown>).type as string});
    deps.handleMessage(ws, session, parsed, connection.signal);
  });

  ws.resume();
}

// Joined as the newest socket on the session, which carries this upgrade's credentials from here on.
function join(session: ChatSession, ws: ExtWebSocket): void {
  openSockets.set(session, [...(openSockets.get(session) ?? []), ws]);
  session.authHeaders = ws.authHeaders;
}

// `undefined` rather than a throw: one store failure closes one socket instead of ending the process.
async function createSession(
  deps: ConnectionHandlerDeps,
  sessionId: string,
  ws: ExtWebSocket
): Promise<ChatSession | undefined> {
  try {
    return await deps.sessionStore.create(sessionId, ws.userId, {
      authHeaders: ws.authHeaders,
      workspaceId: ws.workspaceId,
    });
  } catch (error) {
    log.error('ws', 'session create failed', {userId: ws.userId, error: messageOf(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not start a session');
    return undefined;
  }
}

// The close path erases nothing: the conversation outlives its socket, and `onDisconnect` is the consumer's seam.
function endSession(
  deps: ConnectionHandlerDeps,
  sessionId: string,
  state: {notified: boolean; delivered: boolean},
  held: {session?: ChatSession; socket: ExtWebSocket}
): void {
  if (state.notified) return;
  state.notified = true;

  if (held.session) leave(held.session, held.socket);

  // Only for a session the consumer was actually handed: onDisconnect is the other half of onConnect, not of a socket.
  if (!state.delivered) return;

  runHook('onDisconnect', sessionId, () => deps.onDisconnect?.(sessionId));
}

// The newest socket still open lends the session its credentials; with none left, nothing keeps them or a closed socket.
function leave(session: ChatSession, ws: ExtWebSocket): void {
  const open = openSockets.get(session) ?? [];
  if (!open.includes(ws)) return;
  const remaining = open.filter(socket => socket !== ws);
  const newest = remaining.at(-1);
  if (newest === undefined) {
    openSockets.delete(session);
    session.authHeaders = undefined;
    return;
  }
  openSockets.set(session, remaining);
  session.authHeaders = newest.authHeaders;
}

// Never a resumed session: evict erases, and a resumed session holds the conversation being rejoined.
async function evictUnlessResumed(
  deps: ConnectionHandlerDeps,
  sessionId: string,
  resumed: ChatSession | undefined
): Promise<void> {
  if (!resumed) await evictSession(deps, sessionId);
}

// Only for a session no client ever received: it has no entries and nothing to migrate.
async function evictSession(deps: ConnectionHandlerDeps, sessionId: string): Promise<void> {
  try {
    await deps.sessionStore.evict?.(sessionId);
  } catch (error) {
    log.error('ws', 'session evict failed', {sessionId, error: messageOf(error)});
  }
}

// Consumer hooks are fire-and-forget: the engine never awaits one and never lets one take the connection down.
function runHook(name: string, sessionId: string, call: () => void | Promise<void>): void {
  try {
    // Promise.resolve also absorbs a thenable from another realm, where `instanceof Promise` is false.
    void Promise.resolve(call()).catch((error: unknown) => logHookFailure(name, sessionId, error));
  } catch (error) {
    logHookFailure(name, sessionId, error);
  }
}

function logHookFailure(name: string, sessionId: string, error: unknown): void {
  log.error('ws', `${name} hook failed`, {sessionId, error: messageOf(error)});
}

function messageOf(error: unknown): string {
  if (typeof error === 'object' && error !== null && 'message' in error) return String(error.message);
  return String(error);
}

import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/messages.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {AIError} from '../../types/ai.js';
import type {MessageChunk} from '../../types/ai.js';
import {
  createUserEntry,
  createAssistantEntry,
  createThinkingEntry,
  createToolEntry,
} from '../../orchestration/entryFactories.js';
import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
import {log} from '../../shared/logger.js';

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  suppressOutput: boolean;
  sentAssistantIndices: number[];
}

type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
export function createMessageHandler(orchestrator: ChatOrchestrator) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
  };
}

// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
async function answerInTurn(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    return;
  }
  const startedAt = Date.now();
  try {
    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
  } finally {
    endTurn(ws, session, signal, startedAt);
  }
}

// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
  if (signal?.aborted) {
    log.info('message', 'turn abandoned: its socket closed', {
      sessionId: session.sessionId,
      elapsedMs: Date.now() - startedAt,
    });
    return;
  }
  sendStreamEnd(ws);
}

async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  answerFrame(ws, validation);
}

function answerFrame(ws: WebSocket, validation: ValidationResult): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
  try {
    await action();
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    const code = error instanceof AIError ? error.code : 'UNKNOWN';
    log.error('message', 'handling error', {error: message, code});
    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
      return;
    }
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

async function handleUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  content: string,
  signal: AbortSignal | undefined
): Promise<void> {
  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});

  const userEntry = createUserEntry(content);
  const userIndex = appendEntry(session, userEntry);
  sendUpsert(ws, userIndex, userEntry);

  const parser = new ThinkingTagParser();
  const state: StreamState = {
    thinkingIndex: null,
    assistantIndex: null,
    suppressOutput: false,
    sentAssistantIndices: [],
  };

  let textChunkCount = 0;

  try {
    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
      if (signal?.aborted) break;
      textChunkCount = logChunk(chunk, textChunkCount);
      processChunk(ws, session, state, parser, chunk);
    }
  } finally {
    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
    flushHeldText(ws, session, state, parser);
    closeCutOff(ws, session, state, 'thinkingIndex');
    closeCutOff(ws, session, state, 'assistantIndex');
  }

  if (textChunkCount > 0) {
    log.debug('stream', `received ${textChunkCount} text chunks`);
  }
  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
}

// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
function logChunk(chunk: MessageChunk, textChunkCount: number): number {
  if (chunk.type === 'text') return textChunkCount + 1;

  if (textChunkCount > 0) {
    log.debug('stream', `received ${textChunkCount} text chunks`);
  }

  if (chunk.type === 'tool_result') {
    log.debug('stream', 'tool_result chunk', {
      messageCount: chunk.clientMessages.length,
      types: chunk.clientMessages.map(m => m.type),
    });
    return 0;
  }

  log.debug('stream', 'chunk', {type: chunk.type});
  return 0;
}

function processChunk(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  parser: ThinkingTagParser,
  chunk: MessageChunk
): void {
  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
}

function processTextChunk(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  parser: ThinkingTagParser,
  text: string
): void {
  const segments = parser.push(text);
  for (const segment of segments) {
    handleTextSegment(ws, session, state, segment);
  }
}

function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
  if (segment.type === 'thinking') {
    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
    return;
  }
  commitAndClear(ws, session, state, 'thinkingIndex');
  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
}

function streamSegment(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  key: StateIndexKey,
  createEntry: EntryFactory,
  content: string
): void {
  const isNew = initSegment(session, state, key, createEntry);
  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
  appendDelta(session, state[key]!, content);
  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
}

// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
  markSuppressed(session, index);
  sendSkip(ws, index);
}

function markSuppressed(session: ChatSession, index: number): void {
  const entry = session.entries[index];
  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
}

function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
  if (state[key] !== null) return false;
  state[key] = appendEntry(session, createEntry());
  return true;
}

function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
  const index = state[key];
  if (index === null) return;

  commitEntry(session, index);
  state[key] = null;

  // Only what the client received can be retracted, and only assistant entries.
  if (state.suppressOutput) return;

  sendCommit(ws, index);
  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
}

function processToolUseChunk(
  ws: WebSocket,
  session: ChatSession,
  toolCall: {name: string; input: Record<string, unknown>}
): void {
  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
  const toolIndex = appendEntry(session, toolEntry);
  sendUpsert(ws, toolIndex, toolEntry);
}

function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
  for (const msg of clientMessages) {
    log.debug('stream', 'forwarding client message to frontend', {
      type: msg.type,
      index: 'index' in msg ? msg.index : undefined,
    });
    sendJson(ws, msg);
  }
}

// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
  commitOpenEntries(ws, session, state);
  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});

  for (const idx of state.sentAssistantIndices) {
    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
    markSuppressed(session, idx);
  }

  state.sentAssistantIndices = [];
  state.suppressOutput = true;
}

function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
  flushHeldText(ws, session, state, parser);
  commitOpenEntries(ws, session, state);
}

// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
  for (const segment of parser.flush()) {
    handleTextSegment(ws, session, state, segment);
  }
}

// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
  const index = state[key];
  if (index === null) return;
  markTruncated(session, index);
  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
  commitAndClear(ws, session, state, key);
}

function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
  commitAndClear(ws, session, state, 'thinkingIndex');
  commitAndClear(ws, session, state, 'assistantIndex');
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

